        &lt;div class="view"&gt;View 5&lt;/div&gt;
      &lt;/div&gt;
      &lt;div class="splitter"&gt;&lt;/div&gt;
      &lt;div class="view"&gt;
        &lt;div class="view"&gt;View 6&lt;/div&gt;
